/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
from email.parser import BytesParser
from email.policy import default
from email.header import decode_header, make_header
import re

src = Path.home()/'.thunderbird/t5q2a5hp.default-release/ImapMail/outlook.office365.com/INBOX'
out = Path.home()/'emails.bak'
out.mkdir(exist_ok=True)

# Remove only prior files created by this exporter to avoid stale duplicates while
# leaving any unrelated files in the requested backup directory untouched.
for p in out.glob('inbox_*.eml'):
    p.unlink()

def split_mbox(path):
    current = None
    with path.open('rb') as f:
        for line in f:
            if line.startswith(b'From '):
                if current is not None:
                    yield b''.join(current)
                current = []
            else:
                if current is None:
                    current = []
                current.append(line)
        if current is not None:
            yield b''.join(current)

def clean_subject(raw):
    if not raw:
        return 'no-subject'
    try:
        text = str(make_header(decode_header(raw)))
    except Exception:
        text = raw
    text = re.sub(r'\\s+', ' ', text).strip()
    text = re.sub(r'["'^A-Za-z0-9._ -]+'"', '', text).strip(' ._-')
    return (text[:70] or 'no-subject')

written = []
for i, msg_bytes in enumerate(split_mbox(src), 1):
    try:
        msg = BytesParser(policy=default).parsebytes(msg_bytes)
        subject = clean_subject(msg.get('subject'))
    except Exception:
        subject = 'unparsed'
    name = f'inbox_{i:04d}_{subject}.eml'
    dest = out / name
    # Avoid pathological collisions after subject cleanup.
    n = 2
    while dest.exists():
        dest = out / f'inbox_{i:04d}_{subject}_{n}.eml'
        n += 1
    dest.write_bytes(msg_bytes)
    written.append(dest)

print(f'Exported {len(written)} messages to {out}')
for p in written:
    print(p.name, p.stat().st_size)
PY"

